function validate([nums1, nums2, k]) {
  for (const [name, nums] of [['nums1', nums1], ['nums2', nums2]]) {
    if (!Array.isArray(nums) || nums.length < 1 || nums.length > 500) return `${name} needs 1 to 500 digits.`;
    if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 9)) return `Every value in ${name} is a digit from 0 to 9.`;
    if (nums.length > 1 && nums[0] === 0) return `${name} must not start with a leading zero.`;
  }
  if (!Number.isInteger(k) || k < 1 || k > nums1.length + nums2.length) return 'k is between 1 and the total number of digits.';
  return null;
}

