function maxNumber(nums1, nums2, k) {
  const pickMax = (nums, size) => {
    const stack = [];
    let drop = nums.length - size;
    for (const digit of nums) {
      while (drop > 0 && stack.length > 0 && stack[stack.length - 1] < digit) {
        stack.pop();
        drop--;
      }
      stack.push(digit);
    }
    return stack.slice(0, size).join('');
  };
  const merge = (a, b) => {
    let result = '';
    let i = 0;
    let j = 0;
    while (i < a.length || j < b.length) {
      if (a.slice(i) >= b.slice(j)) {
        result += a[i++];
      } else {
        result += b[j++];
      }
    }
    return result;
  };

  let best = '';
  const low = Math.max(0, k - nums2.length);
  const high = Math.min(k, nums1.length);
  for (let count = low; count <= high; count++) {
    const candidate = merge(pickMax(nums1, count), pickMax(nums2, k - count));
    if (candidate > best) best = candidate;
  }
  return [...best].map(Number);
}

