function maxNumber(nums1, nums2, k) {
  const m = nums1.length;
  const n = nums2.length;
  const firstAt = (nums, from, d) => {
    for (let p = from; p < nums.length; p++) if (nums[p] === d) return p;
    return -1;
  };
  // states: every (i, j) pair of next unused positions reachable with the best prefix so far.
  let states = [[0, 0]];
  const result = [];
  for (let left = k; left > 0; left--) {
    for (let d = 9; d >= 0; d--) {
      const next = [];
      for (const [i, j] of states) {
        const a = firstAt(nums1, i, d);
        if (a >= 0 && (m - a - 1) + (n - j) >= left - 1) next.push([a + 1, j]);
        const b = firstAt(nums2, j, d);
        if (b >= 0 && (m - i) + (n - b - 1) >= left - 1) next.push([i, b + 1]);
      }
      if (next.length > 0) {
        result.push(d);
        // A state that is behind another in both arrays can never do better, so drop it.
        next.sort((x, y) => x[0] - y[0] || x[1] - y[1]);
        states = [];
        for (const s of next) if (states.length === 0 || s[1] < states[states.length - 1][1]) states.push(s);
        break;
      }
    }
  }
  return result;
}

